import { drizzle } from "drizzle-orm/d1";
import type { SessionUser } from "../auth";
import * as schema from "./schema";

// Bindings from wrangler.jsonc (types generated by `npm run cf-typegen`), plus
// the signed-in user that requireAdmin() / requireLeader() / requireMember() put on
// requests, and (requireMember) the roster member they're linked to.
export type AppEnv = { Bindings: Env; Variables: { user: SessionUser; member: { id: number; name: string; memberId: string | null } } };

export function getDb(env: Env) {
  return drizzle(env.DB, { schema });
}
